  const dispatch = async (jobs, { signal } = {}) => {
    const job = jobs[0], actorId = Number(job.id.match(/:actor:(\d+):/)[1]);
    calls.set(actorId, (calls.get(actorId) || 0) + 1);
    if (actorId === 2) {
